async function api(path, method='GET', body) {
  const language=LmuI18n.code;
  let response;
  try{response=await fetch('/api'+path,{method,cache:'no-store',credentials:'same-origin',signal:AbortSignal.timeout(15000),headers:{'Content-Type':'application/json','X-LMU-CSRF':state.csrf,'X-LMU-Language':LmuI18n.code},body:body===undefined?undefined:JSON.stringify(body)});}
  catch(error){throw new Error(error.name==='TimeoutError'?tr("web.theServerIsTakingTooLongToRespond"):tr("web.localWebServerUnreachableCheckTheServerAnd"));}
  if(method==='GET'&&language!==LmuI18n.code)return api(path,method,body);
  if(response.status===204)return null;
  const result = await response.json().catch(()=>({error:tr("web.theServerDidNotSendAReadableResponse")}));
  if(!response.ok){if(response.status===401){$('#shell').hidden=true;$('#pairing').hidden=false;}throw new Error(result.error||tr("web.requestFailed",{value0:(response.status)}));}
  return result;
}
async function connect(key) {const result=await api('/session','POST',{key});state.csrf=result.csrf;await initialize();}
async function initialize() {
  state.catalog=await api('/catalog');$('#pairing').hidden=true;$('#shell').hidden=false;
  if(location.hash.startsWith('#access=')){const page=new URLSearchParams(location.hash.slice(1)).get('page');history.replaceState(null,'',page==='settings'?'#settings':'#dashboard');}
  await renderRoute();
}
$('#pair-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button',e.target);button.disabled=true;try{await connect(new FormData(e.target).get('key'));}catch(error){$('#pair-error').textContent=error.message;}finally{button.disabled=false;}});
async function boot() {
  try {
    const key=new URLSearchParams(location.hash.slice(1)).get('access');
    if(key){const page=new URLSearchParams(location.hash.slice(1)).get('page');history.replaceState(null,'',page==='settings'?'#settings':'#dashboard');await connect(key);return;}
    const session=await api('/session');if(session.authenticated){state.csrf=session.csrf;await initialize();}
    else {$('#pairing').hidden=false;$('#access-key').focus();}
  }catch(error){$('#pairing').hidden=false;$('#pair-error').textContent=error.message;}
}
