function fillCatalog(form,key={}) {
  const vehicle=$('[name=vehicleId]',form),track=$('[name=trackId]',form),layout=$('[name=layoutId]',form);
  const selected={vehicleId:key.vehicleId||vehicle.value,trackId:key.trackId||track.value,layoutId:key.layoutId||layout.value};
  vehicle.innerHTML=options(state.catalog.vehicles,selected.vehicleId,tr("web.selectVehicle"));track.innerHTML=options(state.catalog.tracks,selected.trackId,tr("web.selectTrack"));
  layout.innerHTML=options(state.catalog.layouts.filter(l=>l.trackId===track.value),selected.layoutId,tr("web.selectLayout"));
  const update=()=>{const limits=state.catalog.vehicles.find(v=>v.id===vehicle.value)?.limits;for(const [name,property] of [['tc','tc'],['tcCut','tcCut'],['tcSlip','tcSlip'],['abs','abs']]){const input=$('[name='+name+']',form);if(input){if(limits?.[property]!=null)input.max=limits[property];else input.removeAttribute('max');}}const note=$('#limits-note',form);if(note)note.textContent=limits?tr("web.verifiedVehicleLimitsAreCheckedDuringEntry"):tr("web.maximumLevelsHaveNotBeenVerifiedForThis");};
  vehicle.onchange=update;track.onchange=()=>{layout.innerHTML=options(state.catalog.layouts.filter(l=>l.trackId===track.value),'',tr("web.selectLayout"));};update();
}
