function addCatalog(kind,trackId,entryId=null) {
  const old=entryId?(kind==='vehicle'?state.catalog.vehicles.find(v=>v.id===entryId):kind==='track'?state.catalog.tracks.find(t=>t.id===entryId):state.catalog.layouts.find(l=>l.id===entryId&&l.trackId===trackId)):null;
  const titles={vehicle:tr("web.addVehicle"),track:tr("web.addTrack"),layout:tr("web.addLayout")};
  const editTitles={vehicle:'common.editVehicle',track:'common.editTrack',layout:'common.editLayout'};
  // Nested catalog dialogs during copy would discard unsaved copy inputs. Use catalog page for that case.
  if($('#modal').open){notice(tr("web.registerNewMappingsUnderVehiclesTracksFirst"),true);return;}
  showModal((dialogHead(old?tr(editTitles[kind]):titles[kind])) + (`<form id="catalog-form">
    ${kind==='layout'?`<label for="catalog-track">${h("web.track_b8a24")}</label><select id="catalog-track" name="trackId" required ${old?'disabled':''}>${options(state.catalog.tracks,old?.trackId||trackId||$('#setup-form [name=trackId]')?.value,tr("web.selectTrack"))}</select>`:''}
    <label class="section-gap" for="catalog-id">${esc(kind==='vehicle'?tr("web.lmuVehicleModelId"):kind==='track'?tr("web.lmuTrackId"):tr("web.layoutId"))} *</label>
    <input id="catalog-id" name="id" required maxlength="256" autocomplete="off" value="${esc(old?.id||'')}" ${old?'readonly':''}>
    <p class="field-note">${h("web.useTheExistingTechnicalKeyAManualEntry")}</p>
    <label class="section-gap" for="catalog-name">${h("web.displayName")}</label><input id="catalog-name" name="name" required maxlength="256" value="${esc(old?.name||'')}">
    ${kind==='vehicle'?`<label class="section-gap" for="catalog-class">${h("web.vehicleClass")}</label><input id="catalog-class" name="class" maxlength="256" placeholder="${h("web.eGGt3")}" value="${esc(old?.class||'')}">`:''}
    <p id="dialog-error" class="diff-before" role="alert"></p><div class="dialog-actions"><button type="button" data-action="close-modal">${h("web.cancel")}</button><button type="submit" class="primary">${h("web.saveEntry")}</button></div></form>`));
  $('#catalog-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),body={id:data.get('id'),name:data.get('name')};if(kind==='vehicle')body.class=data.get('class')||null;if(kind==='layout')body.trackId=old?.trackId||data.get('trackId');await busy(async()=>{try{await api('/catalog/'+({vehicle:'vehicles',track:'tracks',layout:'layouts'})[kind],old?'PUT':'POST',old?{expected:catalogRecord(old),replacement:{...catalogRecord(old),...body}}:body);state.catalog=await api('/catalog');$('#modal').close();if($('#setup-form')){const key={};key[kind==='vehicle'?'vehicleId':kind==='track'?'trackId':'layoutId']=body.id;if(kind==='layout')key.trackId=body.trackId;fillCatalog($('#setup-form'),key);state.dirty=true;}else await catalog();notice(tr("web.entrySaved"));}catch(error){$('#dialog-error').textContent=error.message;}});};
}
