async function busy(work) {if(state.busy)return;state.busy=true;const buttons=[...document.querySelectorAll('button:not(:disabled)')];buttons.forEach(b=>b.disabled=true);try{await work();}finally{buttons.forEach(b=>{if(b.dataset.blocked!=='true')b.disabled=false;});state.busy=false;}}
document.addEventListener('click',async e=>{
  const a=e.target.closest('a[href^="#"]');if(a&&state.dirty){if(!confirm(tr("web.discardUnsavedChanges"))){e.preventDefault();return;}state.dirty=false;}
  const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;
  if(action==='close-modal'){$('#modal').close();return;}
  if(action.startsWith('edit-')){addCatalog(action.slice(5),button.dataset.track,button.dataset.id);return;}
  if(action.startsWith('add-')){addCatalog(action.slice(4),button.dataset.track);return;}
  if(action.startsWith('import-')){await importDialog(action.slice(7));return;}
  if(action==='restore-backup'){await restoreDialog();return;}
  if(action==='live-save'){await liveSaveDialog();return;}
  if(action==='copy'){await copyDialog(button.dataset.version);return;}
  await busy(async()=>{try{
    if(action==='backup'){await backup();return;}
    if(action==='favorite'){await api('/setups/'+button.dataset.id+'/favorite','POST',{expectedVersion:button.dataset.version,favorite:button.dataset.value==='true'});notice(tr("web.favoriteUpdated"));await renderRoute();}
    if(action==='restore'){await api('/setups/'+state.detail.id+'/restore','POST',{expectedVersion:state.detail.current.id});notice(tr("web.setupRestored"));await renderRoute();}
    if(action==='delete'){const s=state.detail;showModal((dialogHead(tr("web.moveToTrash"))) + (`<p><strong>${esc(s.current.content.name)}</strong> ${h("web.willBeHiddenFromTheActiveLibraryAll")}</p><div class="dialog-actions"><button data-action="close-modal">${h("web.cancel")}</button><button class="danger" data-action="confirm-delete">${h("web.moveToTrash_eca8b")}</button></div>`));}
    if(action==='confirm-delete'){await api('/setups/'+state.detail.id+'/delete','POST',{expectedVersion:state.detail.current.id});$('#modal').close();notice(tr("web.setupMovedToTrashItCanBeRestored"));location.hash='#trash';}
    if(action==='compare'){const result=await api(`/setups/${state.detail.id}/compare?left=${$('#compare-left').value}&right=${$('#compare-right').value}`);$('#comparison').innerHTML=result.differences.length?`<div class="table-wrap"><table><thead><tr><th>${h("web.field")}</th><th>${h("web.v_0c374",{value0:(result.left.number)})}</th><th>${h("web.v_0c374",{value0:(result.right.number)})}</th></tr></thead><tbody>${result.differences.map(d=>`<tr><td>${esc(d.field)}</td><td class="diff-before">${esc(d.before??'—')}</td><td class="diff-after">${esc(d.after??'—')}</td></tr>`).join('')}</tbody></table></div>`:`<p class="banner">${h("web.noDifferencesInValuesOrMetadata")}</p>`;}
  }catch(error){notice(error.message,true);}});
});
async function renderRoute() {
  if(!state.csrf)return;state.dirty=false;const [route,id]=location.hash.slice(1).split('/');
  const active=['setup','edit','new','version'].includes(route)?'library':route||'dashboard';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===active);if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  try {
    if(route==='library'||route==='trash')await library(route==='trash');else if(route==='setup'&&id)await detail(id);else if((route==='edit'||route==='version')&&id)await editor(id,route==='version');else if(route==='new')await editor();else if(route==='catalog')await catalog();else if(route==='settings')await settingsPage();else if(route==='live-setup')await liveSetupPage();else {await dashboard();await refreshLive();}
    document.title=(route==='setup'&&state.detail?state.detail.current.content.name+' · ':'')+'LMU Setup Manager';
  }catch(error){$('#main').innerHTML=pageHead(tr("web.library"),tr("web.viewUnavailable"),error.message,`<a class="button" href="#library">${h("web.goToLibrary")}</a>`);notice(error.message,true);}
}
