 if(signal.open&&state.popupRender!==signature){state.popupRender=signature;popup.innerHTML=`<div class="panel-head"><h2>${h("web.librarySetupFound")}</h2><button class="icon-button" data-action="signal-close" aria-label="${h("web.closeSetupNotification")}">×</button></div><p class="field-note">${h("web.storedTargetValuesNoChangesToLmu")}</p>${chosen?`<h3>${esc(chosen.name)}</h3><p>${esc(chosen.vehicle)} · ${esc(chosen.track)} · ${esc(chosen.layout)}</p>${readings(chosen.values)}`:`<p>${h("web.multipleMatchingVariantsNoneSelectedAutomatically")}</p>${matches.map(s=>`<section class="signal-choice"><strong>${esc(s.name)}</strong><p>${esc(s.vehicle)} · ${esc(s.track)}</p><div class="row-electronics">${compactReadings(s.values)}</div><button data-select-setup="${s.id}">${h("web.showThisVariant")}</button></section>`).join('')}`}<a class="button" href="#live-setup">${h("web.openLiveSetup")}</a>`;}
