    function filters(){const old=$('#import-filter select')?.value||'';$('#import-filter').innerHTML=kind==='vehicles'?`<label for="import-class">${h("web.lmuClass")}</label><select id="import-class"><option value="">${h("web.allVerifiedClasses")}</option>${[...new Set(preview.choices.map(c=>c.class).filter(Boolean))].sort().map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select>`:`<label for="import-track">${h("web.track")}</label><select id="import-track"><option value="">${h("web.allTracksIndividualLayoutsBelow")}</option>${[...new Map(preview.choices.map(c=>[c.trackId,c.trackName])).entries()].map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('')}</select>`;const select=$('#import-filter select');if([...select.options].some(o=>o.value===old))select.value=old;select.onchange=render;}
